pub struct Vao {
    id: GLuint,
}

impl Vao {
    pub fn new() -> Vao {
        let mut id = 0;
        unsafe { gl::GenVertexArrays(1, &mut id); }
        Vao { id }
    }

    pub fn bind(&self) {
        unsafe { gl::BindVertexArray(self.id); }
    }
}

pub fn store_f32_data(&self, data: &[f32]) {
    self.bind();
    let size = (data.len() * std::mem::size_of::<f32>()) as isize;

    unsafe {
        gl::BufferData(self.r#type, size, data.as_ptr() as *const _, self.usage);
    }
}

macro_rules! gl_check {
    ($call:expr) => {{
        $call;
        let err = unsafe { gl::GetError() };
        if err != gl::NO_ERROR {
            panic!("GL Error {:#x}", err);
        }
    }};
}
